                xmlXIncludeGetLastError(xinc) == XML_ERR_NO_MEMORY);
    }
    xmlXIncludeFreeContext(xinc);

    xmlFuzzResetMallocFailed();
    copy = xmlCopyDoc(doc, 1);
    if (doc != NULL)
        xmlFuzzCheckMallocFailure("xmlCopyNode", copy == NULL);
    xmlFreeDoc(copy);

    xmlFreeDoc(doc);
    xmlFreeParserCtxt(ctxt);
}

    ret = (xmlXIncludeRefPtr) xmlMalloc(sizeof(xmlXIncludeRef));
    if (ret == NULL) {
        xmlXIncludeErrMemory(ctxt);
	return(NULL);
    }

    ref = xmlXIncludeNewRef(ctxt, URL, cur);
    xmlFree(URL);
    if (ref == NULL) {
        xmlFree(fragment);
	return(NULL);
    }

ref = xmlXIncludeAddNode(ctxt, node);
if (ref == NULL)
    return(NULL);
ref->expanding = 1;
ctxt->depth++;
xmlXIncludeLoadNode(ctxt, ref);
ctxt->depth--;

xmlXIncludeCtxtPtr
xmlXIncludeNewContext(xmlDocPtr doc) {
    xmlXIncludeCtxtPtr ret;

    if (doc == NULL)
	return(NULL);
    ret = (xmlXIncludeCtxtPtr) xmlMalloc(sizeof(xmlXIncludeCtxt));
    if (ret == NULL)
	return(NULL);
    memset(ret, 0, sizeof(xmlXIncludeCtxt));
    ret->doc = doc;
    ret->incNr = 0;
    ret->incMax = 0;
    ret->incTab = NULL;
    ret->nbErrors = 0;
    return(ret);
}

xmlFuzzResetMallocFailed();
xinc = xmlXIncludeNewContext(doc);
xmlXIncludeSetFlags(xinc, opts);
xmlXIncludeProcessNode(xinc, (xmlNodePtr) doc);
if (doc != NULL) {
    xmlFuzzCheckMallocFailure("xmlXIncludeProcessNode",
            xinc == NULL ||
            xmlXIncludeGetLastError(xinc) == XML_ERR_NO_MEMORY);
}

xmlXIncludeErrMemory(xmlXIncludeCtxtPtr ctxt)
    xmlRaiseMemoryError(ctxt->errorHandler, NULL, ctxt->errorCtxt,
                        XML_FROM_XINCLUDE, NULL);

xmlXIncludeErrMemory(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node,
                     const char *extra)
    ctxt->nbErrors++;
    __xmlRaiseError(NULL, NULL, NULL, ctxt, node, XML_FROM_XINCLUDE,
                    XML_ERR_NO_MEMORY, XML_ERR_ERROR, NULL, 0,
		    extra, NULL, NULL, 0, 0,
		    "Memory allocation failed : %s\n", extra);
    ctxt->errNo = XML_ERR_NO_MEMORY;
    ctxt->fatalErr = 1;

    ret = (xmlXIncludeRefPtr) xmlMalloc(sizeof(xmlXIncludeRef));
    if (ret == NULL) {
        xmlXIncludeErrMemory(ctxt);
	return(NULL);
    }

xmlXIncludeErrMemory(xmlXIncludeCtxtPtr ctxt)
    xmlRaiseMemoryError(ctxt->errorHandler, NULL, ctxt->errorCtxt,
                        XML_FROM_XINCLUDE, NULL);

xmlXIncludeErrMemory(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node,
                     const char *extra)
    ctxt->nbErrors++;
    __xmlRaiseError(NULL, NULL, NULL, ctxt, node, XML_FROM_XINCLUDE,
                    XML_ERR_NO_MEMORY, XML_ERR_ERROR, NULL, 0,
		    extra, NULL, NULL, 0, 0,
		    "Memory allocation failed : %s\n", extra);
    ctxt->errNo = XML_ERR_NO_MEMORY;
    ctxt->fatalErr = 1;

static xmlXIncludeRefPtr
xmlXIncludeNewRef(xmlXIncludeCtxtPtr ctxt, const xmlChar *URI,
	          xmlNodePtr elem) {
    xmlXIncludeRefPtr ret;

    ret = (xmlXIncludeRefPtr) xmlMalloc(sizeof(xmlXIncludeRef));
